		(this.@degree_day_).Assign(s.@degree_day_);
	}

	public void MoveFrom(Lsurface_MeshSnow s) {
		if (this === s) {
			return;
		}
		this.@identity_ = s.@identity_;
		s.@identity_ = new cpp.Str();
		this.@legacy_identity_ = s.@legacy_identity_;
		s.@legacy_identity_ = new cpp.Str();
		this.@parameters_ = s.@parameters_;
		s.@parameters_ = new Lsurface_ueb_Parameters();
		this.@depletion_curve_ = s.@depletion_curve_;
		this.@forcing_ = s.@forcing_;
		this.@completed_ = s.@completed_;
		this.@last_seconds_ = s.@last_seconds_;
		this.@step_ = s.@step_;
		this.@active_cells_ = s.@active_cells_;
		s.@active_cells_ = new cpp.VecI();
		this.@pack_ = s.@pack_;
		s.@pack_ = new cpp.VecI();
		this.@kind_ = s.@kind_;
		s.@kind_ = new cpp.VecI();
		this.@geometry_ = s.@geometry_;
		s.@geometry_ = new cpp.Vec<Lsurface_MeshSnowGeometry>(Mk.Lsurface_MeshSnowGeometry);
		this.@site_ = s.@site_;
		s.@site_ = new cpp.Vec<Lsurface_ueb_Site>(Mk.Lsurface_ueb_Site);
		this.@held_ = s.@held_;
		s.@held_ = new cpp.Vec<Lsurface_ueb_HeldState>(Mk.Lsurface_ueb_HeldState);
		this.@precipitation_ = s.@precipitation_;
		s.@precipitation_ = new cpp.VecD();
		this.@catch_ = s.@catch_;
		s.@catch_ = new cpp.VecD();
		this.@liquid_rate_ = s.@liquid_rate_;
		s.@liquid_rate_ = new cpp.VecD();
		this.@exposed_ = s.@exposed_;
		s.@exposed_ = new cpp.VecD();
		this.@ground_contact_ = s.@ground_contact_;
		s.@ground_contact_ = new cpp.VecB();
		this.@output_ = s.@output_;
		s.@output_ = new cpp.Vec<Lsurface_SnowOutputs>(Mk.Lsurface_SnowOutputs);
		this.@ledger_ = s.@ledger_;
		s.@ledger_ = new cpp.Vec<Lsurface_MeshSnowLedger>(Mk.Lsurface_MeshSnowLedger);
		this.@degree_day_ = s.@degree_day_;
		s.@degree_day_ = new Lsnow_DegreeDaySnow();
	}

	public static Lsurface_MeshSnow MoveNew(Lsurface_MeshSnow s) {
		Lsurface_MeshSnow o = new Lsurface_MeshSnow(cpp.Raw.V);
		o.MoveFrom(s);
		return o;
	}

	public boolean active() {
		return (!(this.@active_cells_).empty());
	}

}
